{
  "name": "backwpup-pro",
  "repo": "wp-media/backwpup-pro",
  "type": "wordpress-plugin",
  "description": "BackWPup plugin with FREE and PRO editions sharing a common core.",
  "entrypoints": {
    "plugin_bootstrap": "backwpup.php",
    "uninstall": "uninstall.php"
  },
  "editions": {
    "free": {
      "paths": [
        "backwpup.php",
        "inc/",
        "src/",
        "views/",
        "components/",
        "parts/",
        "pages/"
      ],
      "notes": [
        "Shared core and FREE features live here.",
        "FREE must not reference PRO namespaces or classes."
      ]
    },
    "pro": {
      "paths": [
        "inc/Pro/",
        "pro/"
      ],
      "notes": [
        "PRO features extend FREE via composition.",
        "No is_pro() feature flags inside shared services."
      ]
    }
  },
  "areas": [
    {
      "path": "inc/",
      "role": "legacy-php",
      "notes": "Non-namespaced classes, admin pages, job types."
    },
    {
      "path": "inc/Pro/",
      "role": "legacy-php-pro",
      "notes": "PRO-only legacy classes and destinations."
    },
    {
      "path": "src/",
      "role": "namespaced-php",
      "notes": "Services and modern codebase."
    },
    {
      "path": "views/",
      "role": "templates",
      "notes": "PHP templates for admin/restore/notice."
    },
    {
      "path": "components/",
      "role": "template-components",
      "notes": "Reusable UI components."
    },
    {
      "path": "parts/",
      "role": "template-parts",
      "notes": "Template partials."
    },
    {
      "path": "pages/",
      "role": "template-pages",
      "notes": "Page templates."
    },
    {
      "path": "pro/parts/",
      "role": "template-parts-pro",
      "notes": "PRO-only template partials."
    },
    {
      "path": "assets/",
      "role": "source-assets",
      "notes": "Source JS/CSS/images."
    },
    {
      "path": "resources/",
      "role": "source-assets",
      "notes": "Build resources."
    },
    {
      "path": "dist/",
      "role": "built-assets",
      "notes": "Compiled assets."
    },
    {
      "path": "languages/",
      "role": "i18n",
      "notes": "Translations."
    },
    {
      "path": "tests/",
      "role": "tests",
      "notes": "PHP unit/integration tests and fixtures."
    },
    {
      "path": "packages/",
      "role": "local-packages",
      "notes": "Local composer packages."
    },
    {
      "path": "bin/",
      "role": "tooling",
      "notes": "Scripts and helpers."
    },
    {
      "path": "tasks/",
      "role": "tooling",
      "notes": "Project tasks."
    },
    {
      "path": "config/",
      "role": "config",
      "notes": "Build and tooling config."
    },
    {
      "path": "vendor/",
      "role": "third-party",
      "notes": "Composer dependencies (do not edit)."
    },
    {
      "path": "node_modules/",
      "role": "third-party",
      "notes": "NPM dependencies (do not edit)."
    }
  ],
  "tooling": {
    "composer": "composer.json",
    "phpcs": "phpcs.xml",
    "phpstan": "phpstan.neon.dist",
    "node": "package.json",
    "gulp": "gulpfile.ts",
    "tailwind": "tailwind.config.js"
  },
  "notes": [
    "Prefer minimal diffs and avoid unrelated formatting changes.",
    "Do not edit generated output in dist/ unless explicitly requested."
  ]
}

